options.afterRender:
const el = context.element;
if (!el) return;

window.__imsSetFilter = function(filter) {
  if (context.grafana && context.grafana.locationService && typeof context.grafana.locationService.partial === 'function') {
    context.grafana.locationService.partial({
      'var-status_filter': filter
    });
  } else {
    const p = new URLSearchParams(window.location.search);
    p.set('var-status_filter', filter);
    window.history.pushState({}, '', window.location.pathname + '?' + p.toString() + window.location.hash);
    window.dispatchEvent(new PopStateEvent('popstate'));
  }
};

const handleClick = (e) => {
  const pill = e.target.closest('.vcp-fpill, .vcp-kpi-card[data-filter]');
  if (pill) {
    e.preventDefault();
    e.stopPropagation();
    const filter = pill.getAttribute('data-filter');
    if (filter) window.__imsSetFilter(filter);
    return;
  }
};

el.addEventListener('click', handleClick);

return () => {
  el.removeEventListener('click', handleClick);
};

options.helpers:
context.markdown.disable('code');
context.handlebars.registerHelper('hot', (v) => (Number(String(v).replace(/,/g, '')) > 0 ? 'hot' : ''));
context.handlebars.registerHelper('pillBase', (b) => {
  const tr = String(context.grafana.replaceVariables('${__url_time_range}')).replace(/&?timezone=[^&]*/g, '');
  return /^from=[^&]+&to=[^&]+$/.test(tr) ? String(b).replace(/from=\d+&to=\d+/, tr) : String(b);
});

options.styles:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500;600;700;800&display=swap');

.vcp-container {
  /* Approved palette — GRAFANA_DESIGN_SYSTEM.md section 2.1 and the machine
     identity table in section 8. Every semantic colour on this card resolves
     to one of these; nothing below hardcodes a state colour again. */
  --vcp-ok: #22c55e;    --vcp-ok-ink: #4ade80;   --vcp-ok-bg: rgba(34, 197, 94, 0.14);   --vcp-ok-line: #15803d;
  --vcp-warn: #f59e0b;  --vcp-warn-ink: #fbbf24; --vcp-warn-bg: rgba(245, 158, 11, 0.14); --vcp-warn-line: #b45309;
  --vcp-crit: #ef4444;  --vcp-crit-ink: #fca5a5; --vcp-crit-bg: rgba(239, 68, 68, 0.16);  --vcp-crit-line: #b91c1c;
  --vcp-info: #00f2fe;  --vcp-info-ink: #67e8f9; --vcp-info-bg: rgba(0, 242, 254, 0.12);  --vcp-info-line: #0e7490;
  --vcp-accent: #3b82f6; --vcp-accent-ink: #93c5fd; --vcp-accent-bg: rgba(59, 130, 246, 0.14); --vcp-accent-line: #1d4ed8;
  /* Neutral ramp: ink-4 is the floor for text under 11px, because ink-5 sits at
     3.6:1 on these backgrounds and ink-4 clears AA at 6.7:1 or better. */
  --vcp-ink-1: #f8fafc; --vcp-ink-2: #e2e8f0; --vcp-ink-3: #cbd5e1; --vcp-ink-4: #94a3b8; --vcp-ink-5: #64748b;
  --vcp-bg-0: #0c0f14; --vcp-bg-1: #0e1117; --vcp-bg-2: #11141a; --vcp-bg-3: #14171d; --vcp-bg-4: #181b22;
  --vcp-on-ink: #0c0f14;

  /* Type ramp. Tailwind's own ramp starts at 12px, which a card holding 18 stations,
     18 pumps and 10 bath readings per line cannot afford, so the three densest steps
     extend it downward on the same 1px cadence. Nothing on this card is off-ramp. */
  --fs-3xs: 8px; --fs-2xs: 9px; --fs-xs: 10px; --fs-sm: 11px;
  --fs-base: 12px; --fs-md: 14px; --fs-lg: 16px; --fs-xl: 20px;
  /* Spacing: Tailwind's 4px grid (space-0.5 through space-6). */
  --sp-0_5: 2px; --sp-1: 4px; --sp-1_5: 6px; --sp-2: 8px;
  --sp-2_5: 10px; --sp-3: 12px; --sp-4: 16px; --sp-5: 20px; --sp-6: 24px;
  /* Radius and elevation: Tailwind's rounded-* and shadow-* steps. */
  --r-sm: 2px; --r: 4px; --r-md: 6px; --r-lg: 8px; --r-xl: 12px; --r-full: 9999px;
  --sh-sm: 0 1px 2px rgba(0,0,0,0.30);
  --sh-md: 0 4px 6px -1px rgba(0,0,0,0.35), 0 2px 4px -2px rgba(0,0,0,0.30);
  --sh-lg: 0 10px 15px -3px rgba(0,0,0,0.45), 0 4px 6px -4px rgba(0,0,0,0.35);
  /* Motion: Tailwind duration-150/200 with its default easing. */
  --ease: cubic-bezier(0.4, 0, 0.2, 1); --dur-fast: 150ms; --dur: 200ms;
  --vcp-line-1: #1e232f; --vcp-line-2: #232731; --vcp-line-3: #2f3542;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--vcp-ink-2);
  background: transparent;
  padding: 2px 0 6px 0;
  box-sizing: border-box;
}

/* Header Banner */
.vcp-header {
  background: var(--vcp-bg-3);
  border-radius: var(--r-xl);
  padding: var(--sp-3) var(--sp-4);
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--sp-3);
  border: 1px solid var(--vcp-line-2);
  box-shadow: var(--sh-md);
  flex-wrap: wrap;
  gap: var(--sp-2_5);
}
.vcp-title-row {
  display: flex;
  align-items: center;
  gap: var(--sp-3);
}
.vcp-title {
  margin: 0;
  font-size: var(--fs-lg);
  font-weight: 800;
  color: var(--vcp-ink-1);
  letter-spacing: -0.01em;
}
.vcp-live-badge {
  font-size: var(--fs-sm);
  font-weight: 700;
  padding: var(--sp-0_5) var(--sp-2);
  border-radius: var(--r-full);
  background: var(--vcp-ok-bg);
  color: var(--vcp-ok);
  border: 1px solid var(--vcp-ok-line);
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
}
.vcp-live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--vcp-ok-ink);
  display: inline-block;
}
.vcp-header-sub {
  margin-top: var(--sp-1);
  font-size: var(--fs-base);
  color: var(--vcp-ink-4);
  line-height: 1.3;
}

/* Quick Filter Pills */
.vcp-header-left {
  flex: 1 1 auto;
  min-width: 280px;
}
.vcp-filter-pills {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  flex-wrap: wrap;
  margin-left: auto;
  justify-content: flex-end;
}
.vcp-filter-label {
  font-size: var(--fs-sm);
  font-weight: 700;
  color: var(--vcp-ink-4);
  text-transform: uppercase;
  margin-right: var(--sp-0_5);
}
.vcp-fpill {
  padding: var(--sp-1) var(--sp-2_5);
  border-radius: var(--r-lg);
  font-size: var(--fs-sm);
  font-weight: 700;
  text-decoration: none;
  transition: all var(--dur-fast) var(--ease);
  border: 1px solid var(--vcp-line-3);
  background: var(--vcp-bg-2);
  color: var(--vcp-ink-4);
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  cursor: pointer;
}
.vcp-fpill:hover {
  transform: translateY(-1px);
  color: var(--vcp-ink-1);
}
.fpill-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  display: inline-block;
}
.dot-run { background: var(--vcp-ok); }
.dot-idle { background: var(--vcp-info); }
.dot-down { background: var(--vcp-crit); }

.vcp-fpill.is-active {
  color: var(--vcp-ink-1) !important;
  font-weight: 800;
}
/* ALL, RUN and DOWN fill with a bright token, so their label flips to dark ink */
.vcp-fpill.fpill-all.is-active,
.vcp-fpill.fpill-run.is-active,
.vcp-fpill.fpill-down.is-active { color: var(--vcp-on-ink) !important; }
.vcp-fpill.fpill-all.is-active { background: var(--vcp-accent); border-color: var(--vcp-accent); }
.vcp-fpill.fpill-run.is-active { background: var(--vcp-ok); border-color: var(--vcp-ok); }
.vcp-fpill.fpill-idle.is-active { background: var(--vcp-info-line); border-color: var(--vcp-info-line); }
.vcp-fpill.fpill-down.is-active { background: var(--vcp-crit); border-color: var(--vcp-crit); }

/* Real VCP KPI Ribbon */
.vcp-kpi-row {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: var(--sp-2_5);
  margin-bottom: var(--sp-3);
}
.vcp-kpi-card {
  background: var(--vcp-bg-3);
  border-radius: var(--r-lg);
  padding: var(--sp-2_5) var(--sp-2);
  text-align: center;
  border: 1px solid var(--vcp-line-2);
  box-shadow: var(--sh-md);
  transition: transform var(--dur-fast) var(--ease), border-color var(--dur-fast) var(--ease);
  cursor: pointer;
}
.vcp-kpi-card:hover {
  transform: translateY(-2px);
  border-color: var(--vcp-line-3);
}
.vcp-kpi-card.is-active {
  background: var(--vcp-accent-bg);
  border-color: var(--vcp-accent-ink);
}
.vcp-kpi-card.kpi-total { border-top: 3px solid var(--vcp-line-2); }
.vcp-kpi-card.kpi-power { border-top: 3px solid var(--vcp-line-2); cursor: default; }
.vcp-kpi-card.kpi-asd { border-top: 3px solid var(--vcp-line-2); cursor: default; }
.vcp-kpi-card.kpi-speed { border-top: 3px solid var(--vcp-line-2); cursor: default; }
.vcp-kpi-card.kpi-stn { border-top: 3px solid var(--vcp-line-2); cursor: default; }
.vcp-kpi-card.kpi-alarm { border-top: 3px solid var(--vcp-crit); cursor: default; }

.vcp-kpi-title {
  font-size: var(--fs-2xs);
  font-weight: 700;
  color: var(--vcp-ink-4);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: var(--sp-1);
}
.vcp-kpi-val {
  font-size: var(--fs-xl);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: var(--sp-0_5);
  font-family: 'JetBrains Mono', monospace;
}
.kpi-total .vcp-kpi-val { color: var(--vcp-ink-1); }
.kpi-power .vcp-kpi-val { color: var(--vcp-ink-1); }
.kpi-asd .vcp-kpi-val { color: var(--vcp-ink-1); }
.kpi-speed .vcp-kpi-val { color: var(--vcp-ink-1); }
.kpi-stn .vcp-kpi-val { color: var(--vcp-ink-1); }
.kpi-alarm .vcp-kpi-val { color: var(--vcp-crit-ink); }

.vcp-kpi-unit {
  font-size: var(--fs-sm);
  font-weight: 600;
  color: var(--vcp-ink-4);
}
.vcp-kpi-desc {
  font-size: var(--fs-2xs);
  color: var(--vcp-ink-4);
  white-space: nowrap;
}

/* Machine Cards Grid - Exactly 3 Columns */
.vcp-cards-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--sp-3);
}
.vcp-m-card {
  background: var(--vcp-bg-3);
  border-radius: var(--r-xl);
  padding: var(--sp-2_5) var(--sp-3);
  border: 1.5px solid var(--vcp-line-2);
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  gap: var(--sp-1_5);
  box-shadow: var(--sh-md);
  transition: all var(--dur) var(--ease);
  box-sizing: border-box;
}
.vcp-m-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--sh-lg);
}

.vcp-m-card.state-run {
  border-color: var(--vcp-ok);
  box-shadow: var(--sh-md);
}
.vcp-m-card.state-idle {
  border-color: var(--vcp-info-line);
  box-shadow: var(--sh-md);
}
.vcp-m-card.state-down, .vcp-m-card.state-alarm, .vcp-m-card.state-stop {
  border-color: var(--vcp-crit);
  box-shadow: var(--sh-md);
}

/* Card Top Bar */
.vcp-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--sp-0_5);
  padding-bottom: var(--sp-1_5);
  border-bottom: 1px solid var(--vcp-line-1);
}
.vcp-m-title {
  display: flex;
  align-items: center;
  gap: var(--sp-1_5);
  flex-wrap: wrap;
}
.vcp-m-name {
  font-size: var(--fs-md);
  font-weight: 800;
  color: var(--vcp-ink-1);
}
.vcp-m-subcode {
  font-size: var(--fs-xs);
  font-family: 'JetBrains Mono', monospace;
  color: var(--vcp-ink-4);
  background: var(--vcp-bg-0);
  padding: var(--sp-0_5) var(--sp-1);
  border-radius: var(--r);
}
.vcp-waveform-badge {
  font-size: var(--fs-2xs);
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  color: var(--vcp-info);
  background: var(--vcp-info-bg);
  border: 1px solid var(--vcp-info-line);
  padding: var(--sp-0_5) var(--sp-1);
  border-radius: var(--r);
}
.vcp-factory-badge {
  font-size: var(--fs-2xs);
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  color: var(--vcp-accent-ink);
  background: var(--vcp-accent-bg);
  border: 1px solid var(--vcp-accent-line);
  padding: var(--sp-0_5) var(--sp-1);
  border-radius: var(--r);
}
.vcp-status-pill {
  font-size: var(--fs-xs);
  font-weight: 700;
  padding: var(--sp-0_5) var(--sp-1_5);
  border-radius: var(--r-xl);
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
}
.vcp-pill-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  display: inline-block;
}
.state-run .vcp-status-pill { background: var(--vcp-ok-bg); color: var(--vcp-ok-ink); }
.state-run .vcp-pill-dot { background: var(--vcp-ok-ink); }
.state-idle .vcp-status-pill { background: var(--vcp-info-bg); color: var(--vcp-info); }
.state-idle .vcp-pill-dot { background: var(--vcp-info); }
.state-down .vcp-status-pill, .state-alarm .vcp-status-pill, .state-stop .vcp-status-pill { background: var(--vcp-crit-bg); color: var(--vcp-crit); }
.state-down .vcp-pill-dot, .state-alarm .vcp-pill-dot, .state-stop .vcp-pill-dot { background: var(--vcp-crit); }

.vcp-m-timeago {
  font-size: var(--fs-xs);
  color: var(--vcp-ink-4);
  font-weight: 500;
}

/* Core Process Parameters Grid */
.vcp-params-box {
  display: flex !important;
  justify-content: space-between !important;
  gap: var(--sp-3) !important;
  background: var(--vcp-bg-0);
  border-radius: var(--r-lg);
  padding: var(--sp-2) var(--sp-2_5);
  margin-bottom: var(--sp-2);
  border: 1px solid var(--vcp-line-1);
  box-sizing: border-box;
}
.vcp-params-box > p,
.vcp-params-box > br {
  display: none !important;
  margin: 0 !important;
  padding: 0 !important;
}
.vcp-pcol {
  flex: 1 1 0 !important;
  width: 50% !important;
  display: flex !important;
  flex-direction: column !important;
  gap: var(--sp-1) !important;
  box-sizing: border-box;
}
.vcp-prow {
  display: flex !important;
  justify-content: space-between !important;
  align-items: baseline !important;
  gap: var(--sp-1) !important;
}
.vcp-plbl {
  font-size: var(--fs-xs);
  color: var(--vcp-ink-4);
  font-weight: 500;
  white-space: nowrap;
}
.vcp-pval {
  font-size: var(--fs-sm);
  font-weight: 600;
  color: var(--vcp-ink-2);
  text-align: right;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.vcp-pval.lot-code {
  font-family: 'JetBrains Mono', monospace;
  color: var(--vcp-ink-1);
  font-weight: 700;
}
.vcp-pval.asd-hl {
  color: var(--vcp-ink-1);
}
.vcp-val-num {
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  color: var(--vcp-ink-1);
}
.vcp-unit {
  font-size: var(--fs-xs);
  color: var(--vcp-ink-4);
  font-weight: 500;
}

/* Section Header Shared */
.vcp-section-header {
  font-size: var(--fs-2xs);
  font-weight: 700;
  color: var(--vcp-ink-4);
  letter-spacing: 0.04em;
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--sp-1);
}
.vcp-section-tag {
  font-size: var(--fs-2xs);
  color: var(--vcp-ink-4);
  font-family: 'JetBrains Mono', monospace;
}

/* 7-Tank Physical Chemical Sequence */
.vcp-flow-section {
  background: var(--vcp-bg-1);
  border-radius: var(--r-lg);
  padding: var(--sp-2) var(--sp-2);
  margin-bottom: var(--sp-2);
}
.vcp-flow-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: var(--sp-1);
}
.vcp-tank-step {
  background: var(--vcp-bg-3);
  border: 1px solid var(--vcp-line-2);
  border-radius: var(--r-md);
  padding: var(--sp-1) var(--sp-0_5);
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: var(--sp-0_5);
  transition: all var(--dur-fast) var(--ease);
}
.vcp-tank-num {
  font-size: var(--fs-3xs);
  font-weight: 800;
  font-family: 'JetBrains Mono', monospace;
  color: var(--vcp-ink-4);
  line-height: 1;
}
.vcp-tank-name {
  font-size: var(--fs-2xs);
  color: var(--vcp-ink-4);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-weight: 600;
}
.vcp-tank-temp {
  font-size: var(--fs-sm);
  font-weight: 800;
  font-family: 'JetBrains Mono', monospace;
  color: var(--vcp-ink-1);
  line-height: 1.1;
}
.vcp-tank-set {
  font-size: var(--fs-3xs);
  color: var(--vcp-ink-4);
  font-family: 'JetBrains Mono', monospace;
}

.vcp-tank-step.st-ok {
  border-color: var(--vcp-ok);
  background: var(--vcp-ok-bg);
}
.vcp-tank-step.st-ok .vcp-tank-temp { color: var(--vcp-ok-ink); }
.vcp-tank-step.st-ok .vcp-tank-num { color: var(--vcp-ok); }

.vcp-tank-step.st-warn {
  border-color: var(--vcp-warn-line);
  background: var(--vcp-warn-bg);
}
.vcp-tank-step.st-warn .vcp-tank-temp { color: var(--vcp-warn); }
.vcp-tank-step.st-warn .vcp-tank-num { color: var(--vcp-warn-line); }

.vcp-tank-step.st-na {
  border-color: var(--vcp-line-1);
  background: var(--vcp-bg-2);
}
.vcp-tank-step.st-na .vcp-tank-temp { color: var(--vcp-ink-4); }
.vcp-tank-step.st-na .vcp-tank-num { color: var(--vcp-ink-5); }
.vcp-tank-step.st-na .vcp-tank-set { color: var(--vcp-ink-5); }

/* 18 Plating Rectifier Stations Array - 9 cols x 2 rows (Dual Side Amps + Voltage) */
.vcp-stn-grid-9 {
  display: grid;
  grid-template-columns: repeat(9, 1fr);
  gap: 3px;
}
.stn-box {
  border-radius: 3px;
  box-sizing: border-box;
  font-family: 'JetBrains Mono', monospace;
  user-select: none;
  transition: all var(--dur-fast) var(--ease);
}
.stn-box.is-on {
  background: var(--vcp-ok);
  border: 1px solid var(--vcp-ok-line);
  color: var(--vcp-on-ink);
}
.stn-box.is-dev {
  background: var(--vcp-warn-bg);
  border: 1px solid var(--vcp-warn-line);
  color: var(--vcp-warn-ink);
}
.stn-box.is-dev .d3-val,
.stn-box.is-dev .d3-lbl,
.stn-box.is-dev .d3-volt,
.stn-box.is-dev .d3-num {
  color: var(--vcp-warn-ink) !important;
}
.stn-box.is-off {
  background: var(--vcp-bg-4);
  border: 1px solid var(--vcp-line-2);
  color: var(--vcp-ink-4);
  opacity: 0.55;
}
.d3-box {
  height: 38px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 2.5px 2px;
}
.d3-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 9px;
  font-weight: 800;
  opacity: 0.85;
  line-height: 1;
  padding: 0 1px;
}
.d3-num {
  font-weight: 800;
}
.d3-volt {
  font-size: 9px;
  font-weight: 800;
  line-height: 1;
}
.d3-bot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  line-height: 1.1;
  padding: 0 1px;
}
.d3-col {
  display: flex;
  align-items: baseline;
  gap: 1.5px;
}
.d3-lbl {
  font-size: 8.75px;
  font-weight: 900;
  opacity: 0.65;
}
.d3-val {
  font-size: 9.75px;
  font-weight: 900;
  letter-spacing: -0.05em;
}
.d3-div {
  width:1px;
  height: 11px;
  background: currentColor;
  opacity: 0.25;
}
.d3-off {
  margin: auto;
  font-size: 8px;
  font-weight: 700;
  opacity: 0.5;
  letter-spacing: 0.05em;
}
.stn-box.is-off .d3-bot {
  display: none !important;
}
.stn-box.is-on .d3-off,
.stn-box.is-dev .d3-off {
  display: none !important;
}

.vcp-stn-led-grid {
  display: grid;
  grid-template-columns: repeat(9, 1fr);
  gap: var(--sp-1);
}
.vcp-stn-led {
  height: 18px;
  border-radius: var(--r);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--fs-2xs);
  font-weight: 800;
  font-family: 'JetBrains Mono', monospace;
  user-select: none;
  box-sizing: border-box;
  transition: all var(--dur-fast) var(--ease);
  cursor: default;
}
.vcp-stn-led.is-on {
  background: var(--vcp-ok);
  border: 1px solid var(--vcp-ok-line);
  color: var(--vcp-on-ink);
}
.vcp-stn-led.is-off {
  background: var(--vcp-bg-4);
  border: 1px solid var(--vcp-line-2);
  color: var(--vcp-ink-5);
}

/* Stacked 4-Column Ribbon */
.vcp-stacked-ribbon {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--sp-1);
  margin-bottom: var(--sp-2);
  background: var(--vcp-bg-0);
  padding: var(--sp-1_5) var(--sp-1);
  border-radius: var(--r-md);
  border: 1px solid var(--vcp-bg-2);
}
.vcp-stk-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  border-right: 1px solid var(--vcp-line-1);
}
.vcp-stk-item:last-child {
  border-right: none;
}
.vcp-stk-lbl {
  font-size: var(--fs-3xs);
  font-weight: 700;
  color: var(--vcp-ink-4);
  letter-spacing: 0.04em;
  margin-bottom: var(--sp-0_5);
  white-space: nowrap;
}
.vcp-stk-val {
  font-size: var(--fs-base);
  font-weight: 800;
  font-family: 'JetBrains Mono', monospace;
  line-height: 1;
}
.vcp-stk-val.val-amp { color: var(--vcp-info); }
.vcp-stk-val.val-volt { color: var(--vcp-info); }
.vcp-stk-val.val-pump { color: var(--vcp-accent-ink); }
.vcp-stk-val.val-asd { color: var(--vcp-warn-ink); }
.vcp-stk-u {
  font-size: var(--fs-2xs);
  font-weight: 600;
  color: var(--vcp-ink-4);
  margin-left: var(--sp-0_5);
}

/* Card Footer */
.vcp-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--sp-1_5);
  border-top: 1px solid var(--vcp-line-1);
  font-size: var(--fs-xs);
}
.vcp-footer-last { color: var(--vcp-ink-4); }
.vcp-footer-alarm { color: var(--vcp-ink-4); }
.vcp-footer-alarm strong.has-alarm { color: var(--vcp-crit); font-weight: 800; }

.vcp-empty-fleet {
  grid-column: 1 / -1;
  background: var(--vcp-bg-3);
  border: 1px solid var(--vcp-line-2);
  border-radius: var(--r-xl);
  padding: var(--sp-6) var(--sp-5);
  text-align: center;
}
.vcp-empty-title {
  font-size: var(--fs-lg);
  font-weight: 700;
  color: var(--vcp-ink-1);
  margin-bottom: var(--sp-1);
}
.vcp-empty-desc {
  font-size: var(--fs-base);
  color: var(--vcp-ink-4);
}

/* Two-line LED cell: station or pump number over its measured value */
.vcp-stn-led { height: 27px !important; flex-direction: column; gap: 0; line-height: 1.05;}
.vcp-stn-led b { font-size: var(--fs-3xs); font-weight: 800; opacity: 0.72;}
.vcp-stn-led i { font-style: normal; font-size: var(--fs-xs); font-weight: 800;}
/* Running but off recipe: 5 A is the same limit the current-deviation rule fires on */
.vcp-stn-led.is-dev { background: var(--vcp-warn-bg); border: 1px solid var(--vcp-warn-line); color: var(--vcp-warn-ink);}
.vcp-pmp-led.is-on { background: var(--vcp-info-line); border: 1px solid var(--vcp-info-line); color: var(--vcp-info-ink);}
.vcp-pmp-led.is-dev { background: var(--vcp-warn-bg); border: 1px solid var(--vcp-warn-line); color: var(--vcp-warn-ink);}
.vcp-pmp-led.is-off { background: var(--vcp-bg-4); border: 1px solid var(--vcp-line-2); color: var(--vcp-ink-5);}
/* Support baths sit outside the seven-step flow */
.vcp-support-section { background: var(--vcp-bg-1); border-radius: var(--r-lg); padding: var(--sp-2) var(--sp-2); margin-bottom: var(--sp-2);}
.vcp-support-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--sp-1);}
.vcp-pump-section { background: var(--vcp-bg-1); border-radius: var(--r-lg); padding: var(--sp-2) var(--sp-2); margin-bottom: var(--sp-2);}
/* A reading the source gives no setpoint for: neither in nor out of spec */
.vcp-tank-step.st-nospec { border-color: var(--vcp-line-3); background: var(--vcp-bg-2);}
.vcp-tank-step.st-nospec .vcp-tank-temp { color: var(--vcp-ink-3);}
.vcp-tank-step.st-nospec .vcp-tank-num { color: var(--vcp-ink-4);}
/* Dummy and test waveforms must not read as a production run */
.vcp-waveform-badge.wf-dummy { color: var(--vcp-warn-ink); background: var(--vcp-warn-bg); border-color: var(--vcp-warn-line);}

/* Kill the empty paragraphs the renderer inserts between HTML blocks */
.vcp-container > p, .vcp-container > br,
.vcp-cards-grid > p, .vcp-cards-grid > br,
.vcp-m-card > p, .vcp-m-card > br,
.vcp-flow-section > p, .vcp-flow-section > br,
.vcp-support-section > p, .vcp-support-section > br,
.vcp-rectifier-section > p, .vcp-rectifier-section > br,
.vcp-pump-section > p, .vcp-pump-section > br {
  display: none !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* Alarm log: newest triggers on this line */
.vcp-alarm-section { background: var(--vcp-bg-1); border-radius: var(--r-lg); padding: var(--sp-2) var(--sp-2); margin-bottom: var(--sp-2); border: 1px solid var(--vcp-line-1);}
.vcp-alarm-section > p, .vcp-alarm-section > br { display: none !important; margin: 0 !important; padding: 0 !important;}
.vcp-al-list { display: flex; flex-direction: column; gap: var(--sp-0_5);}
.vcp-al-list > p, .vcp-al-list > br { display: none !important;}
.vcp-al-row { display: grid; grid-template-columns: 58px 40px 1fr auto; align-items: baseline; gap: var(--sp-1_5);
  padding: var(--sp-0_5) var(--sp-1); border-radius: var(--r); background: var(--vcp-bg-2); border-left: 2px solid var(--vcp-line-2);}
.vcp-al-row.is-open { border-left-color: var(--vcp-crit); background: var(--vcp-crit-bg);}
.vcp-al-time { font-size: var(--fs-2xs); color: var(--vcp-ink-4); font-family: 'JetBrains Mono', monospace;}
.vcp-al-code { font-size: var(--fs-2xs); font-weight: 800; font-family: 'JetBrains Mono', monospace; text-align: center;
  border-radius: var(--r); padding: 0 3px;}
.vcp-al-code.al-crit { color: var(--vcp-crit-ink); background: var(--vcp-crit-bg);}
.vcp-al-code.al-warn { color: var(--vcp-warn-ink); background: var(--vcp-warn-bg);}
.vcp-al-code.al-none { color: var(--vcp-ink-5); background: transparent;}
.vcp-al-msg { font-size: var(--fs-xs); color: var(--vcp-ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;}
.vcp-al-dur { font-size: var(--fs-2xs); color: var(--vcp-ink-4); font-family: 'JetBrains Mono', monospace; white-space: nowrap;}
.vcp-al-row.is-open .vcp-al-dur { color: var(--vcp-crit-ink); font-weight: 700;}
.vcp-al-top { margin-top: var(--sp-1); font-size: var(--fs-2xs); color: var(--vcp-ink-4); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;}

/* Numbers must not jitter between refreshes: fixed-advance digits everywhere a
   measurement is shown. */
.vcp-kpi-val, .vcp-val-num, .vcp-tank-temp, .vcp-tank-set, .vcp-tank-num,
.vcp-stk-val, .vcp-stn-led, .vcp-al-time, .vcp-al-code, .vcp-al-dur,
.vcp-section-tag, .vcp-m-subcode, .vcp-pval {
  font-variant-numeric: tabular-nums;
  font-feature-settings: 'tnum' 1;
}
/* Keyboard users got no affordance at all on the only two interactive elements. */
.vcp-fpill:focus-visible,
.vcp-kpi-card:focus-visible {
  outline: 2px solid var(--vcp-accent);
  outline-offset: 2px;
  border-radius: var(--r-md);
}
.vcp-fpill:active { transform: translateY(0); }
/* A wall display refreshing every minute should not animate for anyone who asked
   the operating system to stop animating. */
@media (prefers-reduced-motion: reduce) {
  .vcp-fpill, .vcp-kpi-card, .vcp-m-card, .vcp-tank-step, .vcp-stn-led {
    transition: none !important;
  }
  .vcp-fpill:hover, .vcp-kpi-card:hover, .vcp-m-card:hover { transform: none !important; }
}
/* Long Thai strings in the empty state read better balanced than ragged. */
.vcp-empty-title, .vcp-empty-desc { text-wrap: balance; }

/* Section labels are navigation, not data: quiet, uppercase, tracked. */
.vcp-section-header > span:first-child {
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--vcp-ink-4);
}
.vcp-section-tag { color: var(--vcp-ink-4); }
/* The setpoint line wrapped inside the narrow tank cell after the type ramp landed. */
.vcp-tank-set {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* An all-off station or pump array should recede rather than shout in 18 grey boxes. */
.vcp-stn-led.is-off, .vcp-pmp-led.is-off { opacity: 0.55; }
/* One quiet divider between the card head and its body instead of a second border. */
.vcp-params-box { border-color: var(--vcp-line-1); }

/* Overflow guards. A grid item defaults to min-width:auto, so a long reading pushed
   the seventh tank past its cell instead of shortening. */
.vcp-tank-step { min-width: 0; }
.vcp-tank-temp, .vcp-tank-name, .vcp-tank-set {
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* The footer holds two long Thai strings: let them wrap as a pair rather than
   breaking mid-phrase against a fixed space-between. */
.vcp-card-footer {
  flex-wrap: wrap;
  gap: var(--sp-0_5) var(--sp-2);
  align-items: baseline;
}
.vcp-footer-alarm { margin-left: auto; }
/* A section label must never be pushed out by its own counter. */
.vcp-section-header { gap: var(--sp-2); min-width: 0; }
.vcp-section-header > span:first-child { flex: 0 0 auto; }
.vcp-section-tag {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: right;
}
/* Colour legend, so the rule above is self-documenting on the board itself:
   red = critical, amber = off recipe, cyan = informational, green = running,
   neutral = identity or a plain measurement. */

/* a line that has not reported for five minutes: last known values, greyed */
.vcp-m-card.is-stale { filter: grayscale(0.85); opacity: 0.72; }
.vcp-m-card.is-stale .vcp-m-timeago { color: var(--vcp-warn); font-weight: 600; }


/* fixes 2026-09-25: normal cells neutral so an abnormal cell stands out; voltage per side */
.vcp-tank-step.st-ok { border-color: var(--vcp-line-2); background: var(--vcp-bg-3); }
.vcp-tank-step.st-ok .vcp-tank-temp { color: var(--vcp-ink-1); }
.vcp-tank-step.st-ok .vcp-tank-num { color: var(--vcp-ink-4); }
.stn-box.is-on { background: #1f2631; border: 1px solid #3b4658; color: var(--vcp-ink-1); }
.stn-box.is-on .d3-val, .stn-box.is-on .d3-num, .stn-box.is-on .d3-lbl { color: var(--vcp-ink-1); }
.vcp-stn-led.vcp-pmp-led.is-on { background: #1f2631 !important; border-color: #3b4658 !important; color: var(--vcp-ink-1) !important; }
.d3-v { display: block; font-size: 9.5px; font-weight: 600; line-height: 1.1; color: var(--vcp-ink-4); }
.stn-box.is-dev .d3-v { color: var(--vcp-warn-ink); }
.vcp-m-card:hover { transform: none; }
/* the station grid keeps nine equal columns whatever the digits; each side stacks A over V */
.vcp-stn-grid-9 { grid-template-columns: repeat(9, minmax(0, 1fr)); }
.d3-box { height: 48px; overflow: hidden; }
.d3-bot { align-items: flex-start; }
.d3-col { flex-wrap: wrap; justify-content: center; column-gap: 2px; row-gap: 0; min-width: 0; flex: 1 1 0; }
.d3-val { font-size: 11px; letter-spacing: -0.03em; }
.d3-v { flex-basis: 100%; text-align: center; }
.d3-div { height: 22px; align-self: center; }


/* ===== VCP — 03 theme · "energised line" =====
   Electric teal marks what is powered and running (the info token: data, not a verdict).
   Green, amber and red keep their meaning: state and faults only. Line identity follows the
   machine identity palette in GRAFANA_DESIGN_SYSTEM.md section 8. */
.vcp-container {
  --t-energy: #22d3ee; --t-energy-ink: #cffafe; --t-energy-bg: rgba(34, 211, 238, 0.13); --t-energy-line: rgba(34, 211, 238, 0.42);
  --t-flow: #60a5fa; --t-flow-ink: #dbeafe; --t-flow-bg: rgba(96, 165, 250, 0.13); --t-flow-line: rgba(96, 165, 250, 0.40);
  --t-violet: #a78bfa; --t-sky: #38bdf8;
  --id-01: #3b82f6; --id-02: #00f2fe; --id-03: #eab308;
  background: radial-gradient(1200px 500px at 15% -10%, rgba(34, 211, 238, 0.06), transparent 60%), radial-gradient(900px 400px at 100% 0%, rgba(96, 165, 250, 0.05), transparent 60%);
}
.vcp-header { background: linear-gradient(90deg, rgba(34, 211, 238, 0.08), rgba(96, 165, 250, 0.03) 45%, transparent); border-color: rgba(34, 211, 238, 0.18); }
.vcp-title { letter-spacing: 0.01em; }

/* header KPIs: one accent each, numbers large and bright */
.vcp-kpi-card { background: linear-gradient(180deg, rgba(255, 255, 255, 0.025), transparent); }
.vcp-kpi-card.kpi-power { border-top-color: var(--t-energy); }
.vcp-kpi-card.kpi-power .vcp-kpi-val { color: var(--t-energy-ink); }
.vcp-kpi-card.kpi-asd { border-top-color: var(--t-violet); }
.vcp-kpi-card.kpi-asd .vcp-kpi-val { color: #ede9fe; }
.vcp-kpi-card.kpi-speed { border-top-color: var(--t-sky); }
.vcp-kpi-card.kpi-speed .vcp-kpi-val { color: #e0f2fe; }
.vcp-kpi-card.kpi-stn { border-top-color: var(--t-energy); }
.vcp-kpi-card.kpi-stn .vcp-kpi-val { color: var(--t-energy-ink); }
.vcp-kpi-card.kpi-alarm { border-top-color: var(--vcp-line-2); }
.vcp-kpi-card.kpi-alarm .vcp-kpi-val { color: var(--vcp-ink-2); }
.vcp-kpi-card.kpi-alarm.hot { border-top-color: var(--vcp-crit); background: linear-gradient(180deg, rgba(239, 68, 68, 0.10), transparent); }
.vcp-kpi-card.kpi-alarm.hot .vcp-kpi-val { color: #fecaca; }

/* line cards: state on the top edge, identity on the name */
.vcp-m-card { background: linear-gradient(180deg, #121826 0%, #0e131d 100%); border-width: 1px; border-top-width: 3px; }
.vcp-m-card.state-run { border-color: rgba(34, 197, 94, 0.35); border-top-color: var(--vcp-ok); box-shadow: 0 0 0 1px rgba(34, 197, 94, 0.06), 0 8px 24px rgba(0, 0, 0, 0.35); }
.vcp-m-card.state-idle { border-color: rgba(0, 242, 254, 0.28); border-top-color: var(--vcp-info); }
.vcp-m-card.state-down, .vcp-m-card.state-alarm, .vcp-m-card.state-stop { border-color: rgba(239, 68, 68, 0.40); border-top-color: var(--vcp-crit); }
.vcp-m-card.is-stale { border-color: var(--vcp-line-2); border-top-color: var(--vcp-ink-5); filter: saturate(0.35); }
.vcp-m-card[data-line$="01"] .vcp-m-name { box-shadow: inset 3px 0 0 var(--id-01); padding-left: 8px; }
.vcp-m-card[data-line$="02"] .vcp-m-name { box-shadow: inset 3px 0 0 var(--id-02); padding-left: 8px; }
.vcp-m-card[data-line$="03"] .vcp-m-name { box-shadow: inset 3px 0 0 var(--id-03); padding-left: 8px; }

/* baths: in band = cool teal outline, the reading bright; out of band stays amber */
.vcp-tank-step { background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent); }
.vcp-tank-step.st-ok { border-color: var(--t-energy-line); background: linear-gradient(180deg, var(--t-energy-bg), rgba(34, 211, 238, 0.02)); }
.vcp-tank-step.st-ok .vcp-tank-temp { color: var(--t-energy-ink); }
.vcp-tank-step.st-ok .vcp-tank-num { color: var(--t-energy); }

/* rectifiers: a powered side glows teal; deviation amber; off stays dim */
.stn-box.is-on { background: linear-gradient(180deg, rgba(34, 211, 238, 0.20), rgba(34, 211, 238, 0.07)) !important; border: 1px solid var(--t-energy-line) !important; color: var(--t-energy-ink) !important; }
.stn-box.is-on .d3-val { color: #ffffff !important; }
.stn-box.is-on .d3-num, .stn-box.is-on .d3-lbl { color: var(--t-energy) !important; }
.stn-box.is-on .d3-v { color: #a5f3fc; }
.stn-box.is-dev { box-shadow: 0 0 10px rgba(245, 158, 11, 0.25); }

/* pumps: running = flow blue; off setpoint = amber */
.vcp-stn-led.vcp-pmp-led.is-on { background: linear-gradient(180deg, var(--t-flow-bg), rgba(96, 165, 250, 0.05)) !important; border-color: var(--t-flow-line) !important; color: var(--t-flow-ink) !important; }
.vcp-stn-led.vcp-pmp-led.is-dev { box-shadow: 0 0 10px rgba(245, 158, 11, 0.25); }

/* alarm log: an open code keeps its red rule and a faint wash */
.vcp-al-row.is-open { background: linear-gradient(90deg, rgba(239, 68, 68, 0.12), transparent 70%); }

@media (prefers-reduced-motion: reduce) { .vcp-container * { transition: none !important; } }


/* ===== VCP — 03 v3 · readable from across the floor ===== */
.vcp-container { --fs-3xs: 10px; --fs-2xs: 10.5px; --fs-xs: 11px; --fs-sm: 12px; --fs-base: 13px; --fs-md: 15px; --fs-lg: 17px; --fs-xl: 24px; }
.vcp-title { font-size: 20px; }
.vcp-kpi-title { font-size: 12px; letter-spacing: 0.04em; }
.vcp-kpi-val { font-size: 26px; }
.d3-val { font-size: 12.5px; }
.d3-v { font-size: 10.5px; }
.d3-num, .d3-lbl { font-size: 10px; }
.d3-box { height: 50px; }
.vcp-tank-temp { font-size: 14px; }
.vcp-tank-set { font-size: 10.5px; }
.vcp-stn-led b { font-size: 10px; }
.vcp-stn-led i { font-size: 12.5px; }
.vcp-al-row { font-size: 12px; }

/* a little less air between blocks, so the card footer clears the bottom of a 1080 screen */
.vcp-params-box { padding: 6px 10px; margin-bottom: 6px; }
.vcp-support-section { padding: 6px 8px; margin-bottom: 6px; }
.vcp-support-grid .vcp-tank-step { padding-top: 2px; padding-bottom: 2px; }
.vcp-al-row { padding-top: 1px; padding-bottom: 1px; }
.vcp-card-footer { padding-top: 4px; }

/* colour key */
.lg-key { display: inline-flex; align-items: center; gap: 6px; margin-left: 16px; font-size: 12px; color: var(--vcp-ink-3); font-weight: 500; }
.lg-key i { display: inline-block; width: 12px; height: 12px; border-radius: 3px; margin-left: 8px; }
.lg-key i:first-child { margin-left: 0; }
.lg-key .k-run { background: linear-gradient(180deg, rgba(34, 211, 238, 0.45), rgba(34, 211, 238, 0.15)); box-shadow: inset 0 0 0 1px var(--t-energy-line); }
.lg-key .k-dev { background: var(--vcp-warn-bg); box-shadow: inset 0 0 0 1px var(--vcp-warn-line); }
.lg-key .k-crit { background: rgba(239, 68, 68, 0.25); box-shadow: inset 0 0 0 1px var(--vcp-crit); }
.lg-key .k-na { background: var(--vcp-bg-4); box-shadow: inset 0 0 0 1px var(--vcp-line-2); }


/* ===== VCP — 03 v4 · four colours, larger type, fewer numbers =====
   green = normal · amber = off setpoint · red = alarm or down · grey = off or no data.
   Nothing else on the board carries a hue. */
.vcp-container {
  --u-ok: #22c55e; --u-ok-ink: #bbf7d0; --u-ok-bg: rgba(34, 197, 94, 0.16); --u-ok-line: rgba(34, 197, 94, 0.55);
  --u-warn: #f59e0b; --u-warn-ink: #fef3c7; --u-warn-bg: rgba(245, 158, 11, 0.34); --u-warn-line: #f59e0b;
  --u-crit: #ef4444; --u-crit-ink: #fee2e2; --u-crit-bg: rgba(239, 68, 68, 0.30); --u-crit-line: #ef4444;
  --u-off: #64748b; --u-off-ink: #94a3b8; --u-off-bg: #161a21; --u-off-line: #2a303b;
  --fs-3xs: 11px; --fs-2xs: 12px; --fs-xs: 12.5px; --fs-sm: 13.5px; --fs-base: 14.5px; --fs-md: 16px; --fs-lg: 19px; --fs-xl: 26px;
  background: #0d1016;
}
.vcp-header { background: #121620; border-color: var(--vcp-line-3); }
.vcp-title { font-size: 22px; }

/* colour key */
.lg-key { gap: 6px; margin-left: 18px; }
.lg-chip { display: inline-block; padding: 3px 10px; border-radius: 4px; font-size: 13px; font-weight: 600; letter-spacing: 0.01em; }
.lg-chip.c-ok { background: var(--u-ok-bg); box-shadow: inset 0 0 0 1px var(--u-ok-line); color: var(--u-ok-ink); }
.lg-chip.c-warn { background: var(--u-warn-bg); box-shadow: inset 0 0 0 2px var(--u-warn-line); color: var(--u-warn-ink); }
.lg-chip.c-crit { background: var(--u-crit-bg); box-shadow: inset 0 0 0 2px var(--u-crit-line); color: var(--u-crit-ink); }
.lg-chip.c-off { background: var(--u-off-bg); box-shadow: inset 0 0 0 1px var(--u-off-line); color: var(--u-off-ink); }

/* status pills: RUN green, IDLE grey, DOWN red */
.dot-idle, .state-idle .vcp-pill-dot { background: var(--u-off-ink); }
.vcp-fpill.fpill-idle.is-active { background: #334155; border-color: #334155; }
.state-idle .vcp-status-pill { background: #1e2530; color: var(--vcp-ink-3); }
.vcp-status-pill { font-size: 14px; }

/* filter pills: neutral buttons, the dot carries the state colour; the chosen one is outlined */
.vcp-fpill, .vcp-fpill.fpill-all.is-active, .vcp-fpill.fpill-run.is-active, .vcp-fpill.fpill-idle.is-active, .vcp-fpill.fpill-down.is-active { background: #171c25 !important; border: 1px solid #334155 !important; color: var(--vcp-ink-3) !important; font-size: 14px; }
.vcp-fpill.is-active { border: 2px solid #e2e8f0 !important; color: #ffffff !important; }
.dot-run { background: var(--u-ok); } .dot-down { background: var(--u-crit); }
.vcp-kpi-card.is-active { outline: none; box-shadow: none; border-color: var(--vcp-line-3); }
/* waveform tag: text, not a status */
.vcp-waveform-badge, .vcp-waveform-badge.wf-dummy { color: var(--vcp-ink-3); background: #1a202a; border-color: #334155; font-size: 12px; }

/* header strip: numbers white; only the alarm tile may turn red */
.vcp-kpi-row { grid-template-columns: repeat(4, 1fr) !important; }
.vcp-kpi-card, .vcp-kpi-card.kpi-power, .vcp-kpi-card.kpi-stn, .vcp-kpi-card.kpi-total, .vcp-kpi-card.kpi-alarm { background: #131821; border-top-color: #334155; }
.vcp-kpi-card .vcp-kpi-val, .vcp-kpi-card.kpi-power .vcp-kpi-val, .vcp-kpi-card.kpi-stn .vcp-kpi-val, .vcp-kpi-card.kpi-alarm .vcp-kpi-val { color: var(--vcp-ink-1); font-size: 30px; }
.vcp-kpi-title { font-size: 13.5px; }
.vcp-kpi-desc { font-size: 12.5px; }
.vcp-kpi-card.kpi-alarm.hot { border-top-color: var(--u-crit); background: linear-gradient(180deg, rgba(239, 68, 68, 0.18), #131821); }
.vcp-kpi-card.kpi-alarm.hot .vcp-kpi-val { color: #fecaca; }

/* line cards: the top edge is the state, nothing else is coloured by line */
.vcp-m-card { background: #11151d; }
.vcp-m-card[data-line] .vcp-m-name { box-shadow: none; padding-left: 0; font-size: 22px; }
.vcp-m-card.state-run { border-color: rgba(34, 197, 94, 0.35); border-top-color: var(--u-ok); }
.vcp-m-card.state-idle { border-color: var(--vcp-line-3); border-top-color: var(--u-off-ink); }
.vcp-m-timeago { font-size: 13px; }

/* job strip */
.job-strip { display: grid !important; grid-template-columns: 1.5fr 1fr 1fr 1fr 1.3fr; gap: 10px; }
.js-cell { display: flex; flex-direction: column; min-width: 0; gap: 1px; }
.js-cell .vcp-plbl { font-size: 12px; color: var(--vcp-ink-4); }
.js-cell .vcp-pval { font-size: 16px; font-weight: 600; color: var(--vcp-ink-1); text-align: left; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.js-cell .vcp-val-num { font-size: 17px; }
.js-cell .vcp-unit { font-size: 12px; color: var(--vcp-ink-4); font-weight: 500; }

/* baths */
.vcp-tank-step, .vcp-tank-step.st-ok { background: var(--u-ok-bg); border: 1px solid var(--u-ok-line); }
.vcp-tank-step.st-ok .vcp-tank-temp { color: #ffffff; }
.vcp-tank-step.st-ok .vcp-tank-num, .vcp-tank-step.st-ok .vcp-tank-name { color: var(--u-ok-ink); }
.vcp-tank-step.st-ok .vcp-tank-set { display: none; }
.vcp-tank-step.st-warn { background: var(--u-warn-bg); border: 2px solid var(--u-warn-line); }
.vcp-tank-step.st-warn .vcp-tank-temp { color: #ffffff; }
.vcp-tank-step.st-warn .vcp-tank-set, .vcp-tank-step.st-warn .vcp-tank-num, .vcp-tank-step.st-warn .vcp-tank-name { color: var(--u-warn-ink); }
.vcp-tank-step.st-na { background: var(--u-off-bg); border: 1px solid var(--u-off-line); }
.vcp-tank-step.st-na .vcp-tank-temp { color: var(--u-off-ink); }
.vcp-tank-step.st-nospec { background: #171c25; border: 1px solid var(--vcp-line-3); }
.vcp-tank-step.st-nospec .vcp-tank-temp { color: var(--vcp-ink-1); }
.vcp-tank-temp { font-size: 17px; font-weight: 700; }
.vcp-tank-name { font-size: 12px; }
.vcp-tank-set { font-size: 12px; font-weight: 600; }
.vcp-tank-temp.prep-none { font-size: 12px; font-weight: 600; color: var(--vcp-ink-4); line-height: 21px; }
.vcp-tank-step.st-nospec .vcp-tank-set { color: var(--vcp-ink-2); }

/* support baths on one line (name, reading, setpoint when amber), so an amber tile keeps its height
   and the card footer stays on screen */
.vcp-support-grid .vcp-tank-step { flex-direction: row !important; align-items: baseline !important; justify-content: center !important; gap: 8px; height: 34px; padding-top: 0 !important; padding-bottom: 0 !important; align-content: center; flex-wrap: nowrap; }
.vcp-support-grid .vcp-tank-step > span { line-height: 30px; flex: 0 0 auto; overflow: visible; }
.vcp-support-grid .vcp-tank-step { gap: 6px; padding-left: 4px !important; padding-right: 4px !important; }

/* a stale line is grey below its header: its last values are history, not a state; the header keeps
   the amber "No data … ago" so the reason stays readable */
.vcp-m-card.is-stale { filter: none; opacity: 1; }
.vcp-m-card.is-stale > :not(.vcp-card-header) { filter: grayscale(1); opacity: 0.8; }
.vcp-m-card.is-stale, .vcp-m-card.state-run.is-stale, .vcp-m-card.state-idle.is-stale { border-color: var(--vcp-line-3); border-top-color: var(--u-off-ink); }
.vcp-m-card.is-stale .vcp-status-pill { filter: grayscale(1); }

/* rectifiers: amps only, large */
.stn-box.is-on { background: var(--u-ok-bg) !important; border: 1px solid var(--u-ok-line) !important; color: #ffffff !important; box-shadow: none; }
.stn-box.is-on .d3-val { color: #ffffff !important; }
.stn-box.is-on .d3-num, .stn-box.is-on .d3-lbl { color: var(--u-ok-ink) !important; }
.stn-box.is-dev { background: var(--u-warn-bg) !important; border: 2px solid var(--u-warn-line) !important; box-shadow: none; }
.stn-box.is-dev .d3-val { color: #ffffff !important; }
.stn-box.is-dev .d3-num, .stn-box.is-dev .d3-lbl { color: var(--u-warn-ink) !important; }
.stn-box.is-off { background: var(--u-off-bg) !important; border: 1px solid var(--u-off-line) !important; }
/* side A above side B: a 4-digit reading (the data reaches 1000 A) still fits a 1/9-width tile */
.d3-box { height: 52px; padding: 2px 5px !important; }
.d3-top { font-size: 11px; }
.d3-num { font-size: 11.5px; font-weight: 700; }
.d3-bot { flex-direction: column; align-items: stretch !important; gap: 0; line-height: 1.05; }
.d3-div { display: none; }
.d3-col { flex-wrap: nowrap !important; justify-content: space-between !important; align-items: baseline; flex: 0 0 auto !important; }
.d3-lbl { font-size: 11px; opacity: 0.8; }
.d3-val { font-size: 16px; font-weight: 700; letter-spacing: 0 !important; font-variant-numeric: tabular-nums; }
.d3-off { font-size: 12px; color: var(--u-off-ink); }

/* pumps: a number only when the reading is off its setpoint */
.vcp-stn-led.vcp-pmp-led.is-on { background: var(--u-ok-bg) !important; border: 1px solid var(--u-ok-line) !important; color: var(--u-ok-ink) !important; box-shadow: none; }
.vcp-stn-led.vcp-pmp-led.is-dev { background: var(--u-warn-bg) !important; border: 2px solid var(--u-warn-line) !important; color: #ffffff !important; box-shadow: none; }
.vcp-stn-led.vcp-pmp-led.is-off { background: var(--u-off-bg) !important; border: 1px solid var(--u-off-line) !important; color: var(--u-off-ink) !important; opacity: 1; }
.vcp-stn-led.vcp-pmp-led:not(.is-dev) i { display: none; }
.vcp-stn-led.vcp-pmp-led b { font-size: 12.5px; }
.vcp-stn-led.vcp-pmp-led.is-dev i { font-size: 13px; font-weight: 700; }

/* alarms */
.vcp-al-row { font-size: 13.5px; }
.vcp-al-row.is-open { background: linear-gradient(90deg, var(--u-crit-bg), transparent 75%); }
.vcp-al-top, .vcp-card-footer { font-size: 13px; }
.vcp-section-header { font-size: 13.5px; }
.vcp-section-tag { font-size: 12px; }
